// Session material here is an HttpOnly cookie, so document.cookie is blind to it. Three layers,
// each one falling through quietly: embedded state, then a credentialed who-am-I, then the DOM.
let why;
try {
  const el = document.getElementById('__NEXT_DATA__');
  if (el && el.textContent) {
    const root = JSON.parse(el.textContent);
    const seen = new Set(); const stack = [root];
    while (stack.length) {
      const n = stack.pop();
      if (!n || typeof n !== 'object' || seen.has(n)) continue;
      seen.add(n);
      for (const k of Object.keys(n)) {
        const v = n[k];
        if ((k === 'currentUser' || k === 'viewer' || k === 'me') && v && typeof v === 'object' && (v.username || v.id)) {
          return {signed_in: true, as: v.username || v.name || undefined, why: '__NEXT_DATA__.' + k};
        }
        if (v && typeof v === 'object') stack.push(v);
      }
    }
    why = '__NEXT_DATA__ present but names no viewer';
  }
} catch (e) { why = '__NEXT_DATA__ parse failed: ' + e.message; }
try {
  const r = await fetch('/api/v3/me', {credentials: 'include', headers: {accept: 'application/json'}});
  if (r.status === 401 || r.status === 403) return {signed_in: false, why: '/api/v3/me ' + r.status};
  if (r.ok) {
    const j = await r.json();
    const u = (j && (j.user || j.data)) || j;
    // A 200 is not the verdict — the identifying FIELD is. A wrong path answers 200 with HTML or
    // with an unrelated body, and JSON.parse/`username` are what catch that.
    if (u && (u.username || u.id)) return {signed_in: true, as: u.username || undefined, why: '/api/v3/me named a user'};
    why = '/api/v3/me answered 200 with no user field';
  }
} catch (e) { /* endpoint is a hypothesis; failure just means "no answer here" */ }
const mine = document.querySelector('header a[href^="/@"], nav a[href^="/@"], a[href="/dashboard"], a[href*="/new-post"]');
if (mine) {
  const href = mine.getAttribute('href') || '';
  return {signed_in: true, as: href.startsWith('/@') ? href.slice(2) : undefined, why: 'signed-in-only nav link'};
}
const wall = document.querySelector('a[href*="/sign-in"], a[href*="/signin"], a[href*="/login"], a[href*="/sign-up"]');
return {signed_in: false, why: why || (wall ? 'sign-in link in the nav' : 'no signed-in nav link found')};
